CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,display_name text NOT NULL,role text NOT NULL CHECK(role IN ('ADMIN','WAREHOUSE','SHIPPER')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS phone text NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS warehouses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,name text NOT NULL,address text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS user_warehouses(user_id uuid REFERENCES users ON DELETE CASCADE,warehouse_id uuid REFERENCES warehouses ON DELETE CASCADE,PRIMARY KEY(user_id,warehouse_id));
CREATE TABLE IF NOT EXISTS zones(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),warehouse_id uuid NOT NULL REFERENCES warehouses,code text NOT NULL,name text NOT NULL,UNIQUE(warehouse_id,code));
CREATE TABLE IF NOT EXISTS bins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),zone_id uuid NOT NULL REFERENCES zones,code text NOT NULL,UNIQUE(zone_id,code));
CREATE TABLE IF NOT EXISTS categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category_id uuid REFERENCES categories,name text UNIQUE NOT NULL,description text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS variants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products,sku text UNIQUE NOT NULL,barcode text UNIQUE NOT NULL,name text NOT NULL,unit text NOT NULL DEFAULT 'pcs',min_stock numeric(14,3) NOT NULL DEFAULT 0 CHECK(min_stock>=0),track_lot boolean NOT NULL DEFAULT true,track_expiry boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS inventory_levels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),variant_id uuid NOT NULL REFERENCES variants,warehouse_id uuid NOT NULL REFERENCES warehouses,bin_id uuid REFERENCES bins,batch_number text NOT NULL DEFAULT '',expiry_date date,quantity_on_hand numeric(14,3) NOT NULL DEFAULT 0 CHECK(quantity_on_hand>=0),quantity_allocated numeric(14,3) NOT NULL DEFAULT 0 CHECK(quantity_allocated>=0 AND quantity_allocated<=quantity_on_hand),available numeric(14,3) GENERATED ALWAYS AS(quantity_on_hand-quantity_allocated) STORED,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE NULLS NOT DISTINCT(variant_id,warehouse_id,bin_id,batch_number));
CREATE INDEX IF NOT EXISTS inventory_pick_idx ON inventory_levels(warehouse_id,variant_id,expiry_date) WHERE available>0;
CREATE TABLE IF NOT EXISTS purchase_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number text UNIQUE NOT NULL,warehouse_id uuid NOT NULL REFERENCES warehouses,supplier text NOT NULL,status text NOT NULL DEFAULT 'OPEN',created_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS po_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_order_id uuid NOT NULL REFERENCES purchase_orders ON DELETE CASCADE,variant_id uuid NOT NULL REFERENCES variants,quantity numeric(14,3) NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS goods_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number text UNIQUE NOT NULL,purchase_order_id uuid REFERENCES purchase_orders,warehouse_id uuid NOT NULL REFERENCES warehouses,received_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS grn_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),goods_receipt_id uuid NOT NULL REFERENCES goods_receipts ON DELETE CASCADE,variant_id uuid NOT NULL REFERENCES variants,inventory_level_id uuid NOT NULL REFERENCES inventory_levels,quantity_received numeric(14,3) NOT NULL CHECK(quantity_received>0),quantity_damaged numeric(14,3) NOT NULL DEFAULT 0 CHECK(quantity_damaged>=0 AND quantity_damaged<=quantity_received));
CREATE TABLE IF NOT EXISTS sales_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number text UNIQUE NOT NULL,warehouse_id uuid NOT NULL REFERENCES warehouses,customer text NOT NULL,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','ALLOCATED','PICKING','PACKED','SHIPPING','DELIVERED','CANCELLED')),created_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE sales_orders ADD COLUMN IF NOT EXISTS customer_phone text NOT NULL DEFAULT '';
ALTER TABLE sales_orders ADD COLUMN IF NOT EXISTS customer_address text NOT NULL DEFAULT '';
ALTER TABLE sales_orders ADD COLUMN IF NOT EXISTS created_by_name text NOT NULL DEFAULT '';
ALTER TABLE sales_orders ADD COLUMN IF NOT EXISTS created_by_email text NOT NULL DEFAULT '';
ALTER TABLE sales_orders ADD COLUMN IF NOT EXISTS created_by_phone text NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS so_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sales_order_id uuid NOT NULL REFERENCES sales_orders ON DELETE CASCADE,variant_id uuid NOT NULL REFERENCES variants,quantity numeric(14,3) NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sales_order_id uuid UNIQUE NOT NULL REFERENCES sales_orders, idempotency_key text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reservation_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reservation_id uuid NOT NULL REFERENCES reservations,inventory_level_id uuid NOT NULL REFERENCES inventory_levels,variant_id uuid NOT NULL REFERENCES variants,quantity numeric(14,3) NOT NULL CHECK(quantity>0),picked numeric(14,3) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pick_lists(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sales_order_id uuid UNIQUE NOT NULL REFERENCES sales_orders,assigned_to uuid REFERENCES users,status text NOT NULL DEFAULT 'OPEN',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pack_lists(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sales_order_id uuid UNIQUE NOT NULL REFERENCES sales_orders,packed_by uuid REFERENCES users,status text NOT NULL DEFAULT 'OPEN',packed_at timestamptz);
CREATE TABLE IF NOT EXISTS shipments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sales_order_id uuid UNIQUE NOT NULL REFERENCES sales_orders,tracking_number text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'READY',proof_url text,latitude numeric(9,6),longitude numeric(9,6),delivered_at timestamptz);
CREATE TABLE IF NOT EXISTS stocktakes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number text UNIQUE NOT NULL,warehouse_id uuid NOT NULL REFERENCES warehouses,status text NOT NULL DEFAULT 'OPEN',created_by uuid REFERENCES users,approved_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stocktake_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),stocktake_id uuid NOT NULL REFERENCES stocktakes ON DELETE CASCADE,inventory_level_id uuid REFERENCES inventory_levels,variant_id uuid NOT NULL REFERENCES variants,bin_id uuid REFERENCES bins,system_quantity numeric(14,3) NOT NULL,actual_quantity numeric(14,3),variance numeric(14,3) GENERATED ALWAYS AS(actual_quantity-system_quantity) STORED);
CREATE TABLE IF NOT EXISTS inventory_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number text UNIQUE NOT NULL,stocktake_id uuid REFERENCES stocktakes,reason text NOT NULL,approved_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inventory_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),warehouse_id uuid NOT NULL REFERENCES warehouses,variant_id uuid NOT NULL REFERENCES variants,inventory_level_id uuid REFERENCES inventory_levels,transaction_type text NOT NULL,reference_doc_type text NOT NULL,reference_doc_id uuid NOT NULL,qty_on_hand_change numeric(14,3) NOT NULL DEFAULT 0,qty_allocated_change numeric(14,3) NOT NULL DEFAULT 0,balance_after numeric(14,3) NOT NULL,created_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tx_level_time_idx ON inventory_transactions(inventory_level_id,created_at DESC);
CREATE INDEX IF NOT EXISTS tx_reference_idx ON inventory_transactions(reference_doc_type,reference_doc_id);
CREATE TABLE IF NOT EXISTS refresh_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE OR REPLACE FUNCTION forbid_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'inventory_transactions is append-only'; END $$;
DROP TRIGGER IF EXISTS inventory_transactions_immutable ON inventory_transactions;
CREATE TRIGGER inventory_transactions_immutable BEFORE UPDATE OR DELETE ON inventory_transactions FOR EACH ROW EXECUTE FUNCTION forbid_ledger_mutation();
